/// The highway of a Thai row's ref ("1", "3256;4"): the first number the table knows.
pub(crate) fn thai_highway(reference: &str) -> Option<&'static (u16, f64, f64, [f64; 4])> {
    reference.split(';').find_map(|part| {
        let number: u16 = part.trim().parse().ok()?;
        THAI_HIGHWAYS
            .binary_search_by_key(&number, |row| row.0)
            .ok()
            .map(|index| &THAI_HIGHWAYS[index])
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn highways_are_found_by_number_and_their_shares_add_up() {
        assert!(THAI_HIGHWAYS.windows(2).all(|w| w[0].0 < w[1].0));
        for &(number, k, mean, shares) in THAI_HIGHWAYS.iter() {
            assert!(k > 0.0 && mean > 0.0, "{number}");
            assert!((shares.iter().sum::<f64>() - 1.0).abs() < 0.003, "{number}");
        }
        // Motorway 7 carries no motorcycles; Koh Samui's ring road a third of its traffic.
        assert_eq!(thai_highway("7").unwrap().3[3], 0.0);
        assert!(thai_highway("4169").unwrap().3[3] > 0.3);
        assert_eq!(thai_highway("AH2;4").unwrap().0, 4);
        assert!(thai_highway("Sukhumvit").is_none());
    }
}
